/// A delta that is not based on the revision of the state is refused as apply-delta refuses it.
#[test]
fn after_decision_run_example_5() {
    let t: types::TenantState = fixture_fx_tenant_state_29();
    let ctx: types::Context = types::Context {
        tenant: types::TenantId("alpha".to_string()),
        principal: types::Principal::User(types::PrincipalId("alpha:editor".to_string())),
        session: None,
        now: crate::prelude::Timestamp(6000),
        correlation: "test-6000".to_string(),
        verified_address: None,
        idempotency_key: None,
        language: None,
        hop: None,
    };
    let result: types::TransitionResult = fixture_fx_transition_result_5();
    let authority_changed: bool = false;
    assert_eq!(
        after_decision_run(&t, &ctx, &result, authority_changed),
        Err(Failure::Error(types::Rejection::Rejected(
            types::DomainError {
                kind: types::ErrorKind::VersionConflict,
                message:
                    "delta is based on Some(StateRevision(5)), state is at Some(StateRevision(6))"
                        .to_string(),
                evidence: Vec::new(),
                missing: None
            }
        )))
    );
}

