/// Example 1 of `setting-refusal`.
#[test]
fn setting_refusal_example_1() {
    let passed: Vec<types::Check> = vec![types::Check {
        rule: "a".to_string(),
        passed: true,
        detail: "x".to_string(),
    }];
    let kind: types::ErrorKind = types::ErrorKind::InvalidIntent;
    let rule: String = "setting:level_is_open".to_string();
    let message: String = "closed".to_string();
    let want_: types::Rejection = types::Rejection::Rejected(types::DomainError {
        kind: types::ErrorKind::InvalidIntent,
        message: "closed".to_string(),
        evidence: vec![
            types::Check {
                rule: "a".to_string(),
                passed: true,
                detail: "x".to_string(),
            },
            types::Check {
                rule: "setting:level_is_open".to_string(),
                passed: false,
                detail: "closed".to_string(),
            },
        ],
        missing: None,
    });
    assert_eq!(setting_refusal(&passed, &kind, &rule, &message), want_);
}

