fn setting_capability_example_1() {
    let tenant: types::TenantState = fixture_fx_tenant_state_35();
    let ctx: types::Context = types::Context {
        tenant: types::TenantId("alpha".to_string()),
        principal: types::Principal::User(types::PrincipalId("alpha:owner".to_string())),
        session: None,
        now: crate::prelude::Timestamp(6000),
        correlation: "test-5000".to_string(),
        verified_address: None,
        idempotency_key: None,
        language: None,
        hop: None,
    };
    let level: types::SettingLevel = types::SettingLevel::Tenant;
    let evidence: Vec<types::Check> = vec![types::Check {
        rule: "setting:caller_is_a_person".to_string(),
        passed: true,
        detail: "alpha:owner".to_string(),
    }];
    let want_: Vec<types::Check> = vec![
        types::Check {
            rule: "setting:caller_is_a_person".to_string(),
            passed: true,
            detail: "alpha:owner".to_string(),
        },
        types::Check {
            rule: "permission:capability:setting-write-tenant".to_string(),
            passed: true,
            detail: "holds setting-write-tenant".to_string(),
        },
    ];
    assert_eq!(
        setting_capability(&tenant, &ctx, &level, &evidence),
        Ok(want_)
    );
}

